// ─── Helpers ──────────────────────────────────────────────────────────────────
function maskNumber(num: string) {
  const parts = num.split(' ');
  return parts.map((p, i) => (i < 3 ? '••••' : p)).join(' ');
}

function SpendBar({ spent, limit, color }: { spent: number; limit: number; color: string }) {
  const pct = Math.min((spent / limit) * 100, 100);
  const warn = pct > 80;
  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.6 }}>
        <Typography sx={{ fontSize: '0.7rem', color: '#9CA3AF' }}>Spent this month</Typography>
        <Typography sx={{ fontSize: '0.7rem', fontWeight: 700, color: warn ? '#DC2626' : '#374151' }}>
          ${spent.toLocaleString()} / ${limit.toLocaleString()}
        </Typography>
      </Box>
      <Box sx={{ height: 6, borderRadius: 99, bgcolor: '#F1F3F9', overflow: 'hidden' }}>
        <Box sx={{
          height: '100%', borderRadius: 99,
          width: `${pct}%`,
          background: warn
            ? 'linear-gradient(90deg,#DC2626,#EF4444)'
            : `linear-gradient(90deg,${color},${color}cc)`,
          transition: 'width 1s ease',
        }} />
      </Box>
    </Box>
  );
}

// ─── Card Visual (uses real image as background) ───────────────────────────────
function CardVisual({ card }: { card: typeof INITIAL_CARDS[0]; showDetails: boolean }) {
  return (
    <Box
      sx={{
        position: 'relative',
        width: '100%',
        paddingBottom: '62%',   // ~credit-card aspect ratio
        borderRadius: '18px',
        overflow: 'hidden',
        boxShadow: card.status === 'inactive'
          ? '0 8px 24px rgba(0,0,0,0.12)'
          : '0 16px 48px rgba(0,0,0,0.22)',
        filter: card.status === 'inactive' ? 'grayscale(60%) brightness(0.8)' : 'none',
        transition: 'all 0.4s ease',
      }}
    >
      {/* Card background image */}
      <Box
        component="img"
        src={CARD_IMGS[card.img as keyof typeof CARD_IMGS]}
        alt={card.name}
        sx={{
          position: 'absolute', inset: 0,
          width: '100%', height: '100%',
          objectFit: 'cover',
        }}
      />
      {/* Inactive overlay */}
      {card.status === 'inactive' && (
        <Box sx={{
          position: 'absolute', inset: 0,
          bgcolor: 'rgba(0,0,0,0.35)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <Box sx={{
            px: 2.5, py: 1, borderRadius: '20px',
            bgcolor: 'rgba(255,255,255,0.15)',
            backdropFilter: 'blur(8px)',
            border: '1px solid rgba(255,255,255,0.25)',
          }}>
            <Typography sx={{ color: '#fff', fontWeight: 700, fontSize: '0.9rem', letterSpacing: 2 }}>
              CARD LOCKED
            </Typography>
          </Box>
        </Box>
      )}
    </Box>
  );
}

// ─── Add Card Dialog ───────────────────────────────────────────────────────────
function AddCardDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [, setStep] = useState(0);
  const [form, setForm] = useState({ name:'', number:'', expiry:'', cvv:'', holder:'' });
  const [done, setDone] = useState(false);

  const handleSubmit = () => {
    setDone(true);
    setTimeout(() => { setDone(false); setStep(0); setForm({ name:'',number:'',expiry:'',cvv:'',holder:'' }); onClose(); }, 1800);
  };

  return (
    <Dialog
      open={open} onClose={onClose} maxWidth="xs" fullWidth
      slotProps={{ paper: { sx: { borderRadius: '24px', overflow: 'hidden' } } }}
    >
      <Box sx={{ p: 3 }}>
        {/* Header */}
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
          <Typography sx={{ fontSize: '1.1rem', fontWeight: 800, color: '#0F172A' }}>Add New Card</Typography>
          <IconButton size="small" onClick={onClose} sx={{ bgcolor: '#F5F6FA', '&:hover': { bgcolor: '#EDEFF5' } }}>
            <CloseIcon fontSize="small" />
          </IconButton>
        </Box>

        {done ? (
          <Box sx={{ textAlign: 'center', py: 4 }}>
            <Box sx={{
              width: 64, height: 64, borderRadius: '50%',
              bgcolor: '#ECFDF5', display: 'flex', alignItems: 'center', justifyContent: 'center',
              mx: 'auto', mb: 2,
              animation: 'pop 0.4s cubic-bezier(0.34,1.56,0.64,1)',
              '@keyframes pop': { '0%': { transform: 'scale(0)' }, '100%': { transform: 'scale(1)' } },
            }}>
              <CheckIcon sx={{ color: '#059669', fontSize: '2rem' }} />
            </Box>
            <Typography sx={{ fontWeight: 800, fontSize: '1rem', color: '#0F172A' }}>Card Added!</Typography>
            <Typography sx={{ fontSize: '0.78rem', color: '#9CA3AF', mt: 0.5 }}>Your card has been added successfully.</Typography>
          </Box>
        ) : (
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            <TextField size="small" fullWidth label="Card Nickname" placeholder="e.g. My Visa"
              value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
              sx={{ '& .MuiOutlinedInput-root': { borderRadius: '12px' } }}
            />
            <TextField size="small" fullWidth label="Card Number" placeholder="1234 5678 9012 3456"
              value={form.number} onChange={e => setForm(f => ({ ...f, number: e.target.value }))}
              sx={{ '& .MuiOutlinedInput-root': { borderRadius: '12px' } }}
            />
            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1.5 }}>
              <TextField size="small" fullWidth label="Expiry (MM/YY)" placeholder="03/29"
                value={form.expiry} onChange={e => setForm(f => ({ ...f, expiry: e.target.value }))}
                sx={{ '& .MuiOutlinedInput-root': { borderRadius: '12px' } }}
              />
              <TextField size="small" fullWidth label="CVV" placeholder="•••" type="password"
                value={form.cvv} onChange={e => setForm(f => ({ ...f, cvv: e.target.value }))}
                sx={{ '& .MuiOutlinedInput-root': { borderRadius: '12px' } }}
              />
            </Box>
            <TextField size="small" fullWidth label="Cardholder Name" placeholder="John Doe"
              value={form.holder} onChange={e => setForm(f => ({ ...f, holder: e.target.value }))}
              sx={{ '& .MuiOutlinedInput-root': { borderRadius: '12px' } }}
            />
            <Button
              fullWidth variant="contained" onClick={handleSubmit}
              sx={{
                background: 'linear-gradient(135deg,#FA510F,#D94309)',
                borderRadius: '12px', py: 1.4, fontWeight: 700, textTransform: 'none',
                boxShadow: '0 6px 20px rgba(250,81,15,0.35)',
                '&:hover': { background: 'linear-gradient(135deg,#D94309,#B33000)' },
              }}
            >
              Add Card
            </Button>
          </Box>
        )}
      </Box>
    </Dialog>
  );
}

// ─── Card Detail Sheet ─────────────────────────────────────────────────────────
function CardDetailSheet({
  card, open, onClose, onToggleLock
}: {
  card: typeof INITIAL_CARDS[0] | null;
  open: boolean;
  onClose: () => void;
  onToggleLock: (id: number) => void;
}) {
  const [showCVV, setShowCVV] = useState(false);
  const [showNum, setShowNum] = useState(false);
  const [copied, setCopied] = useState(false);

  if (!card) return null;

  const handleCopy = () => {
    navigator.clipboard?.writeText(card.number).catch(() => {});
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <Dialog
      open={open} onClose={onClose} maxWidth="xs" fullWidth
      slotProps={{ paper: { sx: { borderRadius: '24px', overflow: 'hidden', m: { xs: 1, sm: 2 } } } }}
    >
      <Box sx={{ p: 3 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2.5 }}>
          <Typography sx={{ fontSize: '1.1rem', fontWeight: 800, color: '#0F172A' }}>{card.name}</Typography>
          <IconButton size="small" onClick={onClose} sx={{ bgcolor: '#F5F6FA' }}>
            <CloseIcon fontSize="small" />
          </IconButton>
        </Box>

        {/* Card image */}
        <Box sx={{ mb: 2.5 }}>
          <CardVisual card={card} showDetails />
        </Box>

        {/* Card details */}
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, mb: 2.5 }}>
          {/* Number */}
          <Box sx={{ p: 1.5, borderRadius: '12px', bgcolor: '#F8F9FA', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <Box>
              <Typography sx={{ fontSize: '0.65rem', color: '#9CA3AF', mb: 0.2 }}>Card Number</Typography>
              <Typography sx={{ fontSize: '0.9rem', fontWeight: 700, color: '#0F172A', letterSpacing: '0.05em' }}>
                {showNum ? card.number : maskNumber(card.number)}
              </Typography>
            </Box>
            <Box sx={{ display: 'flex', gap: 0.5 }}>
              <IconButton size="small" onClick={() => setShowNum(v => !v)} sx={{ color: '#9CA3AF' }}>
                {showNum ? <EyeOffIcon fontSize="small" /> : <EyeIcon fontSize="small" />}
              </IconButton>
              <IconButton size="small" onClick={handleCopy} sx={{ color: copied ? '#059669' : '#9CA3AF' }}>
                {copied ? <CheckIcon fontSize="small" /> : <CopyIcon fontSize="small" />}
              </IconButton>
            </Box>
          </Box>

          {/* Expiry + CVV */}
          <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1.5 }}>
            <Box sx={{ p: 1.5, borderRadius: '12px', bgcolor: '#F8F9FA' }}>
              <Typography sx={{ fontSize: '0.65rem', color: '#9CA3AF', mb: 0.2 }}>Expiry Date</Typography>
              <Typography sx={{ fontSize: '0.9rem', fontWeight: 700, color: '#0F172A' }}>{card.expiry}</Typography>
            </Box>
            <Box sx={{ p: 1.5, borderRadius: '12px', bgcolor: '#F8F9FA', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <Box>
                <Typography sx={{ fontSize: '0.65rem', color: '#9CA3AF', mb: 0.2 }}>CVV</Typography>
                <Typography sx={{ fontSize: '0.9rem', fontWeight: 700, color: '#0F172A' }}>
                  {showCVV ? card.cvv : '•••'}
                </Typography>
              </Box>
              <IconButton size="small" onClick={() => setShowCVV(v => !v)} sx={{ color: '#9CA3AF' }}>
                {showCVV ? <EyeOffIcon fontSize="small" /> : <EyeIcon fontSize="small" />}
              </IconButton>
            </Box>
          </Box>

          {/* Balance */}
          <Box sx={{ p: 1.5, borderRadius: '12px', bgcolor: '#FFF4F0' }}>
            <Typography sx={{ fontSize: '0.65rem', color: '#FA510F', mb: 0.2, fontWeight: 600 }}>Available Balance</Typography>
            <Typography sx={{ fontSize: '1.3rem', fontWeight: 800, color: '#FA510F' }}>
              ${card.balance.toLocaleString()}
            </Typography>
          </Box>
        </Box>

        {/* Spend bar */}
        <Box sx={{ mb: 2.5 }}>
          <SpendBar spent={card.spent} limit={card.limit} color="#FA510F" />
        </Box>

        {/* Recent transactions */}
        <Typography sx={{ fontSize: '0.82rem', fontWeight: 700, color: '#374151', mb: 1.2 }}>Recent on this card</Typography>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0 }}>
          {card.transactions.map((tx, i) => (
            <Box key={i} sx={{ display: 'flex', justifyContent: 'space-between', py: 1,
              borderBottom: i < card.transactions.length - 1 ? '1px solid rgba(0,0,0,0.05)' : 'none' }}>
              <Box>
                <Typography sx={{ fontSize: '0.82rem', fontWeight: 600, color: '#0F172A' }}>{tx.name}</Typography>
                <Typography sx={{ fontSize: '0.68rem', color: '#9CA3AF' }}>{tx.date}</Typography>
              </Box>
              <Typography sx={{ fontSize: '0.85rem', fontWeight: 700,
                color: tx.amount > 0 ? '#059669' : '#0F172A' }}>
                {tx.amount > 0 ? '+' : ''}${Math.abs(tx.amount).toFixed(2)}
              </Typography>
            </Box>
          ))}
        </Box>

        {/* Actions */}
        <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1.5, mt: 2.5 }}>
          <Button
            fullWidth variant="contained"
            onClick={() => onToggleLock(card.id)}
            startIcon={card.status === 'active' ? <LockIcon /> : <UnlockIcon />}
            sx={{
              background: card.status === 'active'
                ? 'linear-gradient(135deg,#FA510F,#D94309)'
                : 'linear-gradient(135deg,#059669,#047857)',
              borderRadius: '12px', py: 1.2, fontWeight: 700,
              textTransform: 'none', fontSize: '0.82rem',
              boxShadow: card.status === 'active'
                ? '0 4px 14px rgba(250,81,15,0.3)'
                : '0 4px 14px rgba(5,150,105,0.3)',
              '&:hover': { opacity: 0.9 },
            }}
          >
            {card.status === 'active' ? 'Lock Card' : 'Unlock Card'}
          </Button>
          <Button
            fullWidth variant="outlined"
            sx={{
              borderColor: 'rgba(0,0,0,0.12)', color: '#374151',
              borderRadius: '12px', py: 1.2, fontWeight: 700, textTransform: 'none', fontSize: '0.82rem',
              '&:hover': { bgcolor: '#F8F9FA', borderColor: 'rgba(0,0,0,0.2)' },
            }}
          >
            Settings
          </Button>
        </Box>
      </Box>
    </Dialog>
  );
}

// ─── Main Page ─────────────────────────────────────────────────────────────────
export default function Cards() {
  const [cards, setCards] = useState(INITIAL_CARDS);
  const [addOpen, setAddOpen] = useState(false);
  const [detailCard, setDetailCard] = useState<typeof INITIAL_CARDS[0] | null>(null);
  const [detailOpen, setDetailOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'all'|'active'|'inactive'>('all');

  const toggleLock = (id: number) => {
    setCards(prev => prev.map(c =>
      c.id === id ? { ...c, status: c.status === 'active' ? 'inactive' : 'active' } : c
    ));
    if (detailCard?.id === id) {
      setDetailCard(prev => prev ? { ...prev, status: prev.status === 'active' ? 'inactive' : 'active' } : null);
    }
  };

  const openDetail = (card: typeof INITIAL_CARDS[0]) => {
    setDetailCard(card);
    setDetailOpen(true);
  };

  const filtered = cards.filter(c =>
    activeTab === 'all' ? true :
    activeTab === 'active' ? c.status === 'active' : c.status === 'inactive'
  );

  return (
    <Box>
      {/* ── Top action row ── */}
      <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 3 }}>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => setAddOpen(true)}
          sx={{
            background: 'linear-gradient(135deg,#FA510F,#D94309)',
            borderRadius: '12px', py: 1.2, px: 2.5,
            textTransform: 'none', fontWeight: 700,
            boxShadow: '0 6px 20px rgba(250,81,15,0.35)',
            '&:hover': { background: 'linear-gradient(135deg,#D94309,#B33000)' },
          }}
        >
          Add New Card
        </Button>
      </Box>

      {/* ── Quick stats ── */}
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr 1fr', md: 'repeat(4,1fr)' }, gap: 2, mb: 4 }}>
        {QUICK_STATS.map(s => (
          <Box key={s.label} sx={{
            p: { xs: 1.8, sm: 2.2 }, borderRadius: '16px', bgcolor: s.bg,
            position: 'relative', overflow: 'hidden',
            transition: 'transform 0.2s', '&:hover': { transform: 'translateY(-2px)' },
          }}>
            <Box sx={{ position: 'absolute', top: -16, right: -16, width: 60, height: 60,
              borderRadius: '50%', bgcolor: s.color + '18' }} />
            <Typography sx={{ fontSize: '0.65rem', color: '#9CA3AF', fontWeight: 600, mb: 0.3 }}>{s.label}</Typography>
            <Typography sx={{ fontSize: { xs: '1rem', sm: '1.2rem' }, fontWeight: 800, color: '#0F172A', lineHeight: 1.1 }}>
              {s.value}
            </Typography>
            <Typography sx={{ fontSize: '0.67rem', color: s.color, fontWeight: 700, mt: 0.4 }}>{s.change}</Typography>
          </Box>
        ))}
      </Box>

      {/* ── Filter tabs ── */}
      <Box sx={{ display: 'flex', gap: 1, mb: 3 }}>
        {(['all','active','inactive'] as const).map(tab => (
          <Box key={tab} onClick={() => setActiveTab(tab)} sx={{
            px: 2, py: 0.8, borderRadius: '10px', cursor: 'pointer', fontWeight: 700,
            fontSize: '0.8rem', textTransform: 'capitalize',
            bgcolor: activeTab === tab ? '#FA510F' : '#F8F9FA',
            color: activeTab === tab ? '#fff' : '#6B7280',
            boxShadow: activeTab === tab ? '0 4px 12px rgba(250,81,15,0.3)' : 'none',
            transition: 'all 0.2s ease',
          }}>
            {tab === 'all' ? `All (${cards.length})` :
             tab === 'active' ? `Active (${cards.filter(c=>c.status==='active').length})` :
             `Inactive (${cards.filter(c=>c.status==='inactive').length})`}
          </Box>
        ))}
      </Box>

      {/* ── Cards grid ── */}
      <Box sx={{
        display: 'grid',
        gridTemplateColumns: { xs: '1fr', sm: 'repeat(2,1fr)', xl: 'repeat(3,1fr)' },
        gap: 3,
        mb: 4,
      }}>
        {filtered.map(card => (
          <Box
            key={card.id}
            sx={{
              borderRadius: '20px',
              bgcolor: '#FFFFFF',
              border: '1px solid rgba(0,0,0,0.07)',
              boxShadow: '0 2px 16px rgba(0,0,0,0.07)',
              overflow: 'hidden',
              transition: 'all 0.3s cubic-bezier(0.34,1.56,0.64,1)',
              '&:hover': {
                transform: 'translateY(-4px)',
                boxShadow: '0 16px 48px rgba(0,0,0,0.12)',
              },
            }}
          >
            {/* Card image */}
            <Box sx={{ p: 2.5, pb: 2 }}>
              <CardVisual card={card} showDetails={false} />
            </Box>

            {/* Info */}
            <Box sx={{ px: 2.5, pb: 2.5 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 1.5 }}>
                <Box>
                  <Typography sx={{ fontSize: '1rem', fontWeight: 800, color: '#0F172A' }}>{card.name}</Typography>
                  <Typography sx={{ fontSize: '0.72rem', color: '#9CA3AF' }}>
                    {card.type} •••• {card.number.slice(-4)}
                  </Typography>
                </Box>
                <Box sx={{
                  px: 1.2, py: 0.4, borderRadius: '8px',
                  bgcolor: card.status === 'active' ? '#ECFDF5' : '#FEF2F2',
                  color: card.status === 'active' ? '#059669' : '#DC2626',
                  fontSize: '0.68rem', fontWeight: 700,
                  display: 'flex', alignItems: 'center', gap: 0.4,
                }}>
                  {card.status === 'active'
                    ? <><CheckIcon sx={{ fontSize: '0.75rem' }} /> Active</>
                    : <><BlockIcon sx={{ fontSize: '0.75rem' }} /> Locked</>
                  }
                </Box>
              </Box>

              {/* Balance */}
              <Box sx={{ mb: 2, p: 1.5, borderRadius: '12px',
                background: 'linear-gradient(135deg,#FFF4F0,#FEE8DF)' }}>
                <Typography sx={{ fontSize: '0.65rem', color: '#FA510F', fontWeight: 600, mb: 0.2 }}>
                  Available Balance
                </Typography>
                <Typography sx={{ fontSize: '1.4rem', fontWeight: 800, color: '#FA510F' }}>
                  ${card.balance.toLocaleString()}
                </Typography>
              </Box>

              {/* Spend bar */}
              <Box sx={{ mb: 2 }}>
                <SpendBar spent={card.spent} limit={card.limit} color="#FA510F" />
              </Box>

              {/* Action buttons */}
              <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 1 }}>
                <Box
                  onClick={() => openDetail(card)}
                  sx={{
                    py: 1, borderRadius: '10px', cursor: 'pointer',
                    bgcolor: '#FFF4F0', color: '#FA510F',
                    display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 0.4,
                    transition: 'all 0.2s', '&:hover': { bgcolor: '#FFE8DC' },
                  }}
                >
                  <EyeIcon sx={{ fontSize: '1rem' }} />
                  <Typography sx={{ fontSize: '0.62rem', fontWeight: 700 }}>Details</Typography>
                </Box>
                <Box
                  onClick={() => toggleLock(card.id)}
                  sx={{
                    py: 1, borderRadius: '10px', cursor: 'pointer',
                    bgcolor: card.status === 'active' ? '#F8F9FA' : '#ECFDF5',
                    color: card.status === 'active' ? '#374151' : '#059669',
                    display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 0.4,
                    transition: 'all 0.2s', '&:hover': { opacity: 0.85 },
                  }}
                >
                  {card.status === 'active'
                    ? <LockIcon sx={{ fontSize: '1rem' }} />
                    : <UnlockIcon sx={{ fontSize: '1rem' }} />
                  }
                  <Typography sx={{ fontSize: '0.62rem', fontWeight: 700 }}>
                    {card.status === 'active' ? 'Lock' : 'Unlock'}
                  </Typography>
                </Box>
                <Box
                  sx={{
                    py: 1, borderRadius: '10px', cursor: 'pointer',
                    bgcolor: '#F8F9FA', color: '#374151',
                    display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 0.4,
                    transition: 'all 0.2s', '&:hover': { bgcolor: '#EDEFF5' },
                  }}
                >
                  <SettingsIcon sx={{ fontSize: '1rem' }} />
                  <Typography sx={{ fontSize: '0.62rem', fontWeight: 700 }}>Settings</Typography>
                </Box>
              </Box>
            </Box>
          </Box>
        ))}

        {/* Add card placeholder */}
        <Box
          onClick={() => setAddOpen(true)}
          sx={{
            borderRadius: '20px',
            border: '2px dashed rgba(250,81,15,0.3)',
            bgcolor: '#FFFBF9',
            display: 'flex', flexDirection: 'column',
            alignItems: 'center', justifyContent: 'center',
            minHeight: 300, gap: 1.5, cursor: 'pointer',
            transition: 'all 0.25s ease',
            '&:hover': {
              border: '2px dashed #FA510F',
              bgcolor: '#FFF4F0',
              transform: 'translateY(-4px)',
            },
          }}
        >
          <Box sx={{
            width: 52, height: 52, borderRadius: '14px',
            background: 'linear-gradient(135deg,#FA510F,#D94309)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            boxShadow: '0 6px 20px rgba(250,81,15,0.35)',
          }}>
            <AddIcon sx={{ color: '#fff', fontSize: '1.5rem' }} />
          </Box>
          <Typography sx={{ fontSize: '0.9rem', fontWeight: 700, color: '#374151' }}>Add New Card</Typography>
          <Typography sx={{ fontSize: '0.75rem', color: '#9CA3AF', textAlign: 'center', px: 3 }}>
            Link a debit or credit card to your account
          </Typography>
        </Box>
      </Box>

      {/* ── Quick send section ── */}
      <Box sx={{ p: 3, borderRadius: '20px', bgcolor: '#FFFFFF',
        border: '1px solid rgba(0,0,0,0.06)', boxShadow: '0 2px 12px rgba(0,0,0,0.05)' }}>
        <Typography sx={{ fontSize: '1rem', fontWeight: 800, color: '#0F172A', mb: 2 }}>Card Actions</Typography>
        <Box sx={{ display: 'grid', gridTemplateColumns: { xs: 'repeat(2,1fr)', sm: 'repeat(4,1fr)' }, gap: 1.5 }}>
          {[
            { label: 'Send Money',    icon: SendIcon,     color: '#FA510F', bg: '#FFF4F0' },
            { label: 'Transfer',      icon: TransferIcon, color: '#6C63FF', bg: '#F3F2FF' },
            { label: 'Top Up',        icon: NorthEastIcon,color: '#059669', bg: '#ECFDF5' },
            { label: 'Withdraw',      icon: SouthWestIcon,color: '#D97706', bg: '#FFFBEB' },
          ].map(action => (
            <Box key={action.label} sx={{
              p: 2, borderRadius: '14px', bgcolor: action.bg,
              display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 1,
              cursor: 'pointer', transition: 'all 0.2s',
              '&:hover': { transform: 'translateY(-2px)', boxShadow: `0 6px 20px ${action.color}25` },
            }}>
              <Box sx={{
                width: 42, height: 42, borderRadius: '12px',
                bgcolor: action.color + '20',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
              }}>
                <action.icon sx={{ color: action.color, fontSize: '1.2rem' }} />
              </Box>
              <Typography sx={{ fontSize: '0.78rem', fontWeight: 700, color: '#374151' }}>
                {action.label}
              </Typography>
            </Box>
          ))}
        </Box>
      </Box>

      {/* Dialogs */}
      <AddCardDialog open={addOpen} onClose={() => setAddOpen(false)} />
      <CardDetailSheet
        card={detailCard}
        open={detailOpen}
        onClose={() => setDetailOpen(false)}
        onToggleLock={toggleLock}
      />
    </Box>
  );
}